(()=>{"use strict";document.addEventListener("click",t=>{const e=t.target.closest?t.target.closest("a.js-revert"):null;if(!e)return;t.preventDefault(),t.stopPropagation();const r=e.href;try{localStorage.removeItem(r.replace(/&return=[a-zA-Z0-9%]+/,"").replace(/&[a-zA-Z-_]+=[0-9]+/,"")),localStorage.setItem(window.location.pathname+r.split("index.php")[1].split("#")[0],JSON.stringify(["#"+r.split("#")[1]]))}catch(t){}window.location.href=r.split("#")[0]})})();